<?php declare(strict_types=1); ?><!doctype html><html lang="<?= e(\App\Core\Translator::locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Translation management</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:15px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #edf0ed}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}textarea{min-height:50px}button{background:#176b50;color:white;border:0;padding:11px 16px;border-radius:8px;font-weight:700}.key{font-family:monospace;font-size:12px;color:#68756c}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1>Translation management</h1><form method="get" action="/admin/translations"><select name="lang" onchange="this.form.submit()"><?php foreach($languages as $language): ?><option value="<?= e($language['code']) ?>" <?= $language['code']===$locale?'selected':'' ?>><?= e($language['name']) ?> (<?= e($language['code']) ?>)</option><?php endforeach; ?></select></form><form method="post" action="/admin/translations"><?= csrf_field() ?><input type="hidden" name="lang" value="<?= e($locale) ?>"><section class="panel"><table><thead><tr><th>Translation key</th><th>Text</th></tr></thead><tbody><?php foreach($translations as $key=>$value): ?><tr><td class="key"><?= e($key) ?></td><td><textarea name="translations[<?= e($key) ?>]"><?= e($value) ?></textarea></td></tr><?php endforeach; ?></tbody></table><p><button type="submit">Save translations</button></p></section></form><form method="post" action="/admin/translations"><?= csrf_field() ?><input type="hidden" name="lang" value="<?= e($locale) ?>"><section class="panel"><h2>New translation key</h2><input name="new_key" placeholder="translation.key" required><textarea name="new_value" placeholder="Translation text" required></textarea><p><button type="submit">Add new key</button></p></section></form></main></body></html>